'use strict';

const passportUtils = require('../passport/utils');
const deepmerge = require('deepmerge');
const loggerUtils = require('../utils/logger');
const tracer = loggerUtils.getTracer(__filename);
const logger = loggerUtils.getLogger('/jwt-refresh');

// Deduplicates concurrent refresh calls for the same session within this process.
// Key: sessionID, Value: Promise<{user, err}>
const pendingRefreshes = new Map();

// Limits the number of concurrent IAS/XSUAA calls to prevent OOM under thundering herd.
// When the limit is reached, requests proceed with their existing token (backends may
// return 401, which the client handles) rather than queuing unbounded IAS connections.
const MAX_CONCURRENT_REFRESHES = parseInt(process.env.MAX_CONCURRENT_TOKEN_REFRESHES || '20', 10);

// Safety timeout for counter leak: if callUaa never calls back (e.g. hung connection),
// decrement the counter after this many ms to unblock future refreshes.
const REFRESH_TIMEOUT_MS = parseInt(process.env.TOKEN_REFRESH_TIMEOUT_MS || '30000', 10);

let activeRefreshCount = 0;

/**
 * Lazy token refresh middleware for non-sticky mode.
 *
 * Only registered by bootstrap.js when non-sticky mode is active —
 * no stickiness check needed here. bootstrap.js uses isSessionStickinessEnabled()
 * at startup to decide which middleware to register.
 *
 * Flow:
 *   1. Token not yet in refresh window → next() immediately (hot path, zero overhead)
 *   2. Token in refresh window or expired, refresh succeeds → update req.session, next()
 *   3. Token in refresh window, refresh fails → if token still valid continue with existing token;
 *      if already expired extend expiryDate by jwtRefresh window + random jitter (0-60s) to prevent re-auth cascade (e.g. 429 storm)
 *   4. Token expired, refresh fails 400 (another instance already refreshed)
 *      → re-fetch fresh session from Redis, overwrite req.session.user, next()
 *   5. Concurrent requests for same session within this process share one refresh call.
 */
module.exports = function lazyJwtRefreshMiddleware(req, res, next) {
  if (!req.session || !req.session.user || !req.session.user.token) {
    return next();
  }

  const token = req.session.user.token;

  if (!token.expiryDate) {
    return next();
  }

  const jwtRefresh = req.routerConfig && req.routerConfig.jwtRefresh;
  const jwtRefreshMs = (jwtRefresh && jwtRefresh > 0) ? jwtRefresh * 60 * 1000 : 0;
  const refreshThreshold = Date.now() + jwtRefreshMs;

  // Token not yet within the refresh window — proceed immediately
  if (token.expiryDate > refreshThreshold) {
    return next();
  }

  const tokenAlreadyExpired = token.expiryDate <= Date.now();
  const sessionId = req.sessionID;

  const oauthOptions = token.oauthOptions;
  if (!oauthOptions || !oauthOptions.tokenURL || !token.refreshToken) {
    tracer.info('Lazy refresh: missing oauthOptions or refreshToken for session %s — skipping', sessionId);
    return next();
  }

  // If a refresh is already in progress for this session in this process, wait for it.
  // Deep-copy result.user so concurrent waiters don't share a mutable reference.
  if (pendingRefreshes.has(sessionId)) {
    tracer.info('Lazy refresh: refresh already in progress for session %s — waiting', sessionId);
    pendingRefreshes.get(sessionId).then(result => {
      if (result && result.user) {
        req.session.user = deepmerge({}, result.user, { arrayMerge: (_dest, source) => source });
      } else if (tokenAlreadyExpired) {
        const jitterMs = Math.floor(Math.random() * 60000);
        req.session.user.token.expiryDate = Date.now() + jwtRefreshMs + jitterMs;
      }
      next();
    }).catch(() => next());
    return;
  }

  tracer.info('Lazy refresh: token within refresh window for session %s (expired=%s) — refreshing inline',
    sessionId, tokenAlreadyExpired);

  // Concurrency cap: if too many refreshes are already in flight, skip and continue
  // with the existing token to prevent OOM from thousands of concurrent IAS connections.
  if (activeRefreshCount >= MAX_CONCURRENT_REFRESHES) {
    if (tracer.isEnabled('debug')) {
      tracer.debug('Lazy refresh: concurrency limit (%d) reached for session %s — skipping refresh',
        MAX_CONCURRENT_REFRESHES, sessionId);
    }
    if (tokenAlreadyExpired) {
      // Extend by jwtRefresh window + random jitter (0-60s) so sessions don't all
      // retry simultaneously, spreading the refresh load over time.
      const jitterMs = Math.floor(Math.random() * 60000);
      req.session.user.token.expiryDate = Date.now() + jwtRefreshMs + jitterMs;
    }
    return next();
  }

  activeRefreshCount++;

  const requestOptions = {
    url: oauthOptions.tokenURL,
    form: {
      'grant_type': 'refresh_token',
      'refresh_token': token.refreshToken,
      'app_tid': oauthOptions.apptid
    }
  };

  if (oauthOptions.certificate) {
    requestOptions.cert = oauthOptions.certificate;
    requestOptions.key = oauthOptions.key;
    requestOptions.form['client_id'] = oauthOptions.clientid;
  } else {
    requestOptions.auth = {
      user: oauthOptions.clientid,
      pass: oauthOptions.clientsecret
    };
  }

  let callbackFired = false;
  const refreshPromise = new Promise(resolve => {
    // Safety timeout: if callUaa never calls back, decrement the counter and resolve
    // with an error so waiters are not blocked and the cap does not leak permanently.
    const safetyTimer = setTimeout(() => {
      if (callbackFired) { return; }
      callbackFired = true;
      pendingRefreshes.delete(sessionId);
      activeRefreshCount--;
      logger.error('Lazy refresh: timeout waiting for token endpoint response for session %s', sessionId);
      resolve({ err: new Error('token refresh timeout') });
    }, REFRESH_TIMEOUT_MS);

    passportUtils.callUaa(Object.assign(requestOptions, {
      retryCondition: function(error) {
        if (error && error.response && error.response.status >= 400 && error.response.status < 500) {
          return false;
        }
        return !!(error && (!error.response || error.response.status !== 200));
      }
    }), null, function (err, uaaResponse) {
      if (callbackFired) { return; }
      callbackFired = true;
      clearTimeout(safetyTimer);
      pendingRefreshes.delete(sessionId);
      activeRefreshCount--;

      if (!err && uaaResponse && uaaResponse.access_token) {
        const options = {
          accessToken: uaaResponse.access_token,
          idToken: uaaResponse.id_token,
          expiresIn: uaaResponse.expires_in,
          refreshToken: uaaResponse.refresh_token,
          scope: uaaResponse.scope,
          oauthOptions: token.oauthOptions
        };
        let updatedUser;
        try {
          updatedUser = deepmerge(req.session.user, passportUtils.getUserProperties(options), {
            arrayMerge: (_dest, source) => source
          });
        } catch (getUserPropErr) {
          logger.error('Lazy refresh: getUserProperties failed for session %s: %s', sessionId, getUserPropErr.message);
          return resolve({ err: getUserPropErr });
        }
        req.session.user = updatedUser;
        tracer.info('Lazy refresh: token refreshed successfully for session %s', sessionId);
        return resolve({ user: updatedUser });
      }

      if (err && err.status === 400) {
        tracer.info('Lazy refresh: 400 from token endpoint for session %s — another instance already refreshed, re-fetching from Redis', sessionId);
        const memoryStore = req.app.get('memoryStore');
        memoryStore.inFlightSessions.delete(sessionId);
        memoryStore.get(sessionId, function (redisErr, freshSession) {
          if (!redisErr && freshSession && freshSession.user && freshSession.user.token && freshSession.user.token.accessToken) {
            req.session.user = freshSession.user;
            tracer.info('Lazy refresh: re-fetched fresh session from Redis for session %s', sessionId);
            return resolve({ user: freshSession.user });
          } else {
            logger.error('Lazy refresh: failed to re-fetch session from Redis for session %s: %s', sessionId, redisErr && redisErr.message);
            return resolve({ err });
          }
        });
        return;
      }

      const reason = err ? err.message : 'unexpected response shape (missing access_token)';
      logger.error('Lazy refresh: token refresh failed for session %s: %s', sessionId, reason);
      resolve({ err });
    });
  });

  // Register BEFORE awaiting so any concurrent request arriving after this line
  // finds the promise in the map and waits rather than starting a duplicate refresh.
  pendingRefreshes.set(sessionId, refreshPromise);

  refreshPromise.then(result => {
    if (!result.user && tokenAlreadyExpired) {
      // Jittered backoff: spread retries over jwtRefresh window + 0-60s
      const jitterMs = Math.floor(Math.random() * 60000);
      req.session.user.token.expiryDate = Date.now() + jwtRefreshMs + jitterMs;
    }
    next();
  }).catch(() => next());
};
